	@Test
	void filterSidecarUsesVersionEightAndRejectsStamplessVersionFive(@TempDir File dataDir) throws IOException {
		LmdbStore writer = initializedStore(dataDir);
		try {
			recordFilterOutcome(writer, filter("5"), 20L, 80L);
		} finally {
			writer.shutDown();
		}

		Path sidecar;
		try (var files = Files.walk(dataDir.toPath())) {
			sidecar = files.filter(path -> path.getFileName().toString().endsWith(".filters"))
					.findFirst()
					.orElseThrow();
		}
		byte[] bytes = Files.readAllBytes(sidecar);
		assertEquals(8, ByteBuffer.wrap(bytes).getInt(), "new filter evidence must use the version-eight format");

		// A version-5 file has no data stamp after the 24-byte identity — drop it along with the version.
		byte[] versionFive = new byte[bytes.length - Long.BYTES];
		System.arraycopy(bytes, 0, versionFive, 0, 4 + 24);
		System.arraycopy(bytes, 4 + 24 + Long.BYTES, versionFive, 4 + 24, bytes.length - 4 - 24 - Long.BYTES);
		ByteBuffer.wrap(versionFive).putInt(5);
		Files.write(sidecar, versionFive);
		LmdbStore reader = initializedStore(dataDir);
		try {
			try (PlanningStatisticsRead read = openPlanningStatistics(reader)) {
				assertNoLearnedFilterEvidence(read.statistics(), filter("5"),
						"stampless evidence must not be loaded as an exact surface");
				assertNoLearnedFilterEvidence(read.statistics(), filter("6"),
						"stampless evidence must not be loaded as a generalized surface");
			}
		} finally {
			reader.shutDown();
		}
	}

